PREFIX brick: <http://brickschema.org/schema/1.2/brick#>
SELECT ?zoneName ?ts WHERE {
  ?z a brick:Zone ; rdfs:label ?zoneName .
  ?s a brick:AirTemperatureSensor ; brick:pointOf ?z .
  ?s ref:hasTimeseriesId ?ts .
}

SELECT ?s ?type ?target ?ts WHERE {
  ?s a ?type .
  FILTER(LCONTAINS(STR(?type), "Temperature"))
  OPTIONAL { ?s <https://brickschema.org/schema/Brick#isPointOf> ?target }
  OPTIONAL { ?s <https://brickschema.org/schema/Brick/ref#hasTimeseriesId> ?ts }
} LIMIT 40

SELECT ?zone ?zlabel ?s ?type ?ts WHERE {
  ?z a <https://brickschema.org/schema/Brick#Zone> .
  ?z rdfs:label ?zlabel .
  ?s <https://brickschema.org/schema/Brick#isPointOf> ?z .
  ?s a ?type .
  OPTIONAL { ?s <https://brickschema.org/schema/Brick/ref#hasTimeseriesId> ?ts }
}

SELECT ?z ?zlabel ?s ?type WHERE {
  ?z a <https://brickschema.org/schema/Brick#Zone> .
  ?z rdfs:label ?zlabel .
  ?s <https://brickschema.org/schema/Brick#isPointOf> ?z .
  ?s a ?type .
}

SELECT ?zlabel ?s ?slabel ?type WHERE {
  ?z a <https://brickschema.org/schema/Brick#HVAC_Zone> .
  ?z rdfs:label ?zlabel .
  ?s <https://brickschema.org/schema/Brick#isPointOf> ?z .
  OPTIONAL { ?s rdfs:label ?slabel }
  ?s a ?type .
}

SELECT ?s ?ref ?ts WHERE {
  ?s a <https://brickschema.org/schema/Brick#Zone_Air_Temperature_Sensor> .
  ?s <https://brickschema.org/schema/Brick/ref#hasExternalReference> ?ref .
  ?ref <https://brickschema.org/schema/Brick/ref#hasTimeseriesId> ?ts .
}

SELECT ?zlabel ?s WHERE {
  ?z a <https://brickschema.org/schema/Brick#HVAC_Zone> .
  ?z rdfs:label ?zlabel .
  ?s <https://brickschema.org/schema/Brick#isPointOf> ?z .
  ?s a <https://brickschema.org/schema/Brick#Zone_Air_Temperature_Sensor> .
}

SELECT ?zlabel ?vav ?zname WHERE {
  ?z a <https://brickschema.org/schema/Brick#HVAC_Zone> .
  ?z rdfs:label ?zlabel .
  ?vav <https://brickschema.org/schema/Brick#controls> ?z .
  OPTIONAL { ?vav rdfs:label ?zname }
}

